(function () {const grid = document.querySelector(".tool-grid");const cards = grid ? [...grid.querySelectorAll(".tool-card")] : [];if (!cards.length) return;const container = document.createElement("div");container.className = "tool-filters";container.innerHTML = `<div class="filter-row"><input type="search" id="tool-search" class="filter-search" placeholder="Search 67 tools..." autocomplete="off"><div class="filter-chips" id="filter-chips"></div></div>`;const parent = grid.parentNode;const heading = parent.querySelector(".section-heading");if (heading) {heading.after(container);} else {parent.insertBefore(container, grid);}const searchInput = container.querySelector("#tool-search");const chipsContainer = container.querySelector("#filter-chips");const categories = [...new Set(cards.map(c => c.dataset.category).filter(Boolean))].sort();const categoryNames = {};categories.forEach(cat => {const label = cards.find(c => c.dataset.category === cat)?.dataset.categoryLabel || cat;categoryNames[cat] = label;});let activeCategory = "";function renderChips() {chipsContainer.innerHTML = categories.map(cat =>`<button class="chip${activeCategory === cat ? " active" : ""}" data-category="${cat}">${categoryNames[cat]}</button>`).join("");if (activeCategory) {chipsContainer.innerHTML += `<button class="chip chip-clear" id="chip-clear">Clear</button>`;setTimeout(() => {const clearBtn = document.getElementById("chip-clear");if (clearBtn) clearBtn.addEventListener("click", () => {activeCategory = "";searchInput.value = "";renderChips();filterCards();});}, 0);}}renderChips();function filterCards() {const query = searchInput.value.toLowerCase().trim();let visible = 0;cards.forEach(card => {const name = (card.dataset.toolName || "").toLowerCase();const keywords = (card.dataset.keywords || "").toLowerCase();const cat = card.dataset.category || "";const catMatch = !activeCategory || cat === activeCategory;const searchMatch = !query || name.includes(query) || keywords.includes(query);const show = catMatch && searchMatch;card.style.display = show ? "" : "none";if (show) visible++;});let countEl = document.getElementById("filter-count");if (!countEl) {countEl = document.createElement("p");countEl.id = "filter-count";countEl.className = "filter-count";container.appendChild(countEl);}countEl.textContent = visible === cards.length? `Showing all ${cards.length} tools`: `Showing ${visible} of ${cards.length} tools`;countEl.setAttribute("aria-live", "polite");}searchInput.addEventListener("input", filterCards);chipsContainer.addEventListener("click", (e) => {const chip = e.target.closest(".chip");if (!chip || chip.id === "chip-clear") return;const cat = chip.dataset.category;activeCategory = activeCategory === cat ? "" : cat;renderChips();filterCards();});searchInput.addEventListener("keydown", (e) => {if (e.key === "Escape") {searchInput.value = "";activeCategory = "";renderChips();filterCards();}});})();